def topo_sort(graph):
    # 状态: 0=未访问, 1=访问中, 2=已访问
    state = {node: 0 for node in graph}
    # 确保所有邻居节点也包含在state中（处理孤立的邻居节点）
    for neighbors in graph.values():
        for neighbor in neighbors:
            if neighbor not in state:
                state[neighbor] = 0
    result = []

    def dfs(node):
        if state[node] == 1:  # 检测到环
            raise ValueError("Graph contains a cycle")
        if state[node] == 2:
            return
        state[node] = 1  # 标记为访问中
        for neighbor in graph.get(node, []):
            dfs(neighbor)
        state[node] = 2  # 标记为已访问
        result.append(node)

    for node in list(state.keys()):  # 遍历所有节点（包括孤立邻居）
        if state[node] == 0:
            dfs(node)
    return result
```

